<script setup lang="ts">
import { computed, ref } from 'vue'
import ActionMenu, { type MenuAction } from './ActionMenu.vue'
import CategoryIcon from './CategoryIcon.vue'
import {statisticsSummary} from './ledger'
import UiIcon from './UiIcon.vue'
import { bookSummary, money } from './ledgerViewModels'
import type { Book, Transaction } from './ledger'
const props=defineProps<{books:Book[];transactions:Transaction[]}>()
const emit=defineEmits<{open:[book:Book];create:[];edit:[book:Book];pin:[book:Book];delete:[book:Book];export:[book:Book,format:'html'|'md'|'csv']}>()
const search=defineModel<string>('search',{default:''})
const sort=ref<'recent'|'name'|'count'>('recent')
const sortLabels={recent:'最近开始',name:'按名称',count:'流水最多'}
const sortActions:MenuAction[]=[{id:'recent',label:'最近开始',icon:'calendar'},{id:'name',label:'按名称排列',icon:'sort'},{id:'count',label:'流水最多',icon:'list'}]
const summaries=computed(()=>new Map(props.books.map(book=>[book.id,bookSummary(book,props.transactions)])))
const overview=computed(()=>{const ids=new Set(props.books.map(book=>book.id));const rows=props.transactions.filter(tx=>tx.bookIds.some(id=>ids.has(id)));return statisticsSummary(rows)})
const results=computed(()=>props.books.filter(book=>[book.name,book.note,book.destination].some(value=>value?.toLocaleLowerCase().includes(search.value.trim().toLocaleLowerCase()))).sort((a,b)=>sort.value==='name'?a.name.localeCompare(b.name,'zh-CN'):sort.value==='count'?(summaries.value.get(b.id)!.count-summaries.value.get(a.id)!.count)||a.name.localeCompare(b.name,'zh-CN'):(b.startDate||'').localeCompare(a.startDate||'')||a.name.localeCompare(b.name,'zh-CN')))
const sections=computed(()=>[{label:'置顶账本',pinned:true,books:results.value.filter(book=>book.isPinned)},{label:results.value.some(book=>book.isPinned)?'其他账本':'全部账本',pinned:false,books:results.value.filter(book=>!book.isPinned)}].filter(section=>section.books.length))
function period(book:Book){const format=(date:string)=>date.replaceAll('-','.');if(book.startDate)return book.endDate?`${format(book.startDate)} — ${format(book.endDate)}`:`${format(book.startDate)} 起`;return book.endDate?`截至 ${format(book.endDate)}`:'未限定期间'}
function actions(book:Book):MenuAction[]{return[{id:'edit',label:'账本设置',icon:'edit'},{id:'pin',label:book.isPinned?'取消置顶':'置顶账本',icon:'pin'},{id:'export',label:'导出账本',icon:'export',children:[{id:'export:html',label:'网页报告 HTML',icon:'book'},{id:'export:md',label:'Markdown 文档',icon:'list'},{id:'export:csv',label:'表格 CSV',icon:'list'}]},{id:'delete',label:'删除账本',icon:'trash',danger:true}]}
function handleAction(book:Book,id:string){if(id==='edit')emit('edit',book);else if(id==='pin')emit('pin',book);else if(id==='delete')emit('delete',book);else if(id.startsWith('export:'))emit('export',book,id.slice(7) as 'html'|'md'|'csv')}
</script>
<template>
  <section class="ledger-view book-library">
    <div class="bl-intro"><div><h2>我的账本</h2><p>把日常、旅行和共同开销，各自收好。</p></div><button type="button" class="lv-button primary" @click="emit('create')"><UiIcon name="plus" :size="16"/>新建账本</button></div>
    <div class="bl-overview"><div><small>全部账本</small><b>{{ books.length }}<span> 本</span></b></div><div><small>账本内支出</small><b class="lv-expense">{{ money(overview.expense) }}</b></div><div><small>账本内收入</small><b class="lv-income">{{ money(overview.income) }}</b></div></div>
    <div class="bl-toolbar"><label class="lv-search"><UiIcon name="search"/><input v-model="search" placeholder="搜索账本名称、备注或目的地" aria-label="搜索账本"/><button v-if="search" type="button" aria-label="清除账本搜索" @click="search=''"><UiIcon name="close" :size="14"/></button></label><ActionMenu :actions="sortActions" label="账本排序" @select="sort=$event as typeof sort"><template #trigger><UiIcon name="sort" :size="16"/><span>{{ sortLabels[sort] }}</span></template></ActionMenu></div>
    <section v-for="section in sections" :key="section.label" class="bl-section"><header><h3><UiIcon v-if="section.pinned" name="pin" :size="13"/>{{ section.label }}</h3><span>{{ section.books.length }} 本</span></header>
      <div class="bl-grid"><article v-for="book in section.books" :key="book.id" class="bl-card" :style="{'--book-color':book.color||'#529de0'}">
        <button class="bl-open" type="button" :aria-label="`打开账本${book.name}`" @click="emit('open',book)"><div class="bl-card-heading"><span class="bl-icon"><CategoryIcon :name="book.icon||'book'" :color="book.color" :size="24"/></span><div class="bl-name"><h3>{{ book.name }}</h3><span class="bl-type"><UiIcon :name="book.participants.length>1?'users':'book'" :size="12"/>{{ book.participants.length>1?'多人分账':book.type==='trip'?'旅行账本':'个人记账' }}</span></div></div><p v-if="book.note||book.destination" class="bl-note">{{ book.note||book.destination }}</p>
          <div class="bl-balance"><span>账本净额</span><strong :class="{'lv-expense':summaries.get(book.id)!.balance<0}">{{ money(summaries.get(book.id)!.balance) }}</strong></div>
          <div class="bl-flows"><span><small>支出</small><b class="lv-expense">{{ money(summaries.get(book.id)!.expense) }}</b></span><span><small>收入</small><b class="lv-income">{{ money(summaries.get(book.id)!.income) }}</b></span></div>
          <div v-if="book.budgetLimitAmount" class="bl-budget"><div><span>预算使用</span><span>{{ Math.round(summaries.get(book.id)!.expense/book.budgetLimitAmount*100) }}%</span></div><i><b :style="{width:`${Math.min(100,summaries.get(book.id)!.expense/book.budgetLimitAmount*100)}%`}"/></i></div>
          <footer><span class="bl-period"><UiIcon name="calendar" :size="13"/><span>{{ period(book) }}</span></span><span>{{ summaries.get(book.id)!.count }} 笔流水</span></footer>
        </button>
        <div class="bl-card-menu"><ActionMenu :actions="actions(book)" :label="`${book.name}的更多操作`" @select="handleAction(book,$event)"/></div>
      </article></div>
    </section>
    <div v-if="!results.length" class="bl-empty"><span><UiIcon :name="search?'search':'book'" :size="29"/></span><h3>{{ search?'没有找到匹配的账本':'创建你的第一本账本' }}</h3><p>{{ search?'试试其他名称、备注或目的地。':'把相关的收支放在一起，记录会更清楚。' }}</p><button class="lv-button" type="button" @click="search?search='':emit('create')">{{ search?'清除搜索':'新建账本' }}</button></div>
  </section>
</template>
<style scoped>
.book-library{display:grid;gap:20px;padding-bottom:24px;}.bl-intro{display:flex;align-items:center;justify-content:space-between;gap:12px;}.bl-intro h2{margin:0 0 6px;font-size:23px;letter-spacing:-.6px;}.bl-intro p{margin:0;color:var(--lv-muted);font-size:12px;line-height:1.6;}
.bl-overview{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;}.bl-overview>div{min-width:0;display:flex;flex-direction:column;gap:10px;padding:17px 18px;border:1px solid var(--lv-line);border-radius:16px;background:var(--lv-paper);}.bl-overview small{color:var(--lv-muted);font-size:11px;}.bl-overview b{overflow:hidden;text-overflow:ellipsis;font-size:20px;letter-spacing:-.5px;font-variant-numeric:tabular-nums;white-space:nowrap;}.bl-overview b span{color:var(--lv-muted);font-size:11px;font-weight:400;}
.bl-toolbar{display:flex;align-items:center;gap:12px;}.bl-toolbar>.lv-search{flex:1;}.bl-toolbar :deep(.lv-menu-trigger){min-height:40px;padding:8px 12px;border-color:var(--lv-line);background:var(--lv-paper);font-size:11px;color:var(--lv-muted);white-space:nowrap;}
.bl-section>header{display:flex;align-items:center;justify-content:space-between;margin:0 3px 11px;}.bl-section>header h3{display:flex;align-items:center;gap:7px;margin:0;font-size:13px;font-weight:650;}.bl-section>header h3 :deep(svg){color:#dba14b;}.bl-section>header>span{color:var(--lv-muted);font-size:10px;}.bl-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,290px),1fr));gap:15px;}
.bl-card{position:relative;min-width:0;border:1px solid color-mix(in srgb,var(--book-color) 20%,var(--lv-line));border-radius:20px;background:color-mix(in srgb,var(--book-color) 3%,var(--lv-paper));transition:border-color .18s,box-shadow .18s,transform .18s;}.bl-card:hover{border-color:color-mix(in srgb,var(--book-color) 45%,var(--lv-line));box-shadow:0 7px 23px #102b3910;transform:translateY(-2px);}.bl-open{display:flex;flex-direction:column;align-items:stretch;width:100%;height:100%;padding:19px 18px 14px;border:0;border-radius:20px;background:transparent;color:var(--lv-ink);text-align:left;font:inherit;cursor:pointer;}.bl-open:focus-visible{outline:2px solid var(--lv-accent);outline-offset:3px;}.bl-card-heading{display:flex;align-items:center;gap:12px;padding-right:30px;}.bl-icon{display:grid;place-items:center;width:45px;height:45px;flex:none;border-radius:15px;background:color-mix(in srgb,var(--book-color) 13%,var(--lv-paper));}.bl-name{min-width:0;}.bl-name h3{overflow:hidden;margin:0 0 8px;text-overflow:ellipsis;white-space:nowrap;font-size:16px;font-weight:650;}.bl-type{display:inline-flex;align-items:center;gap:4px;color:var(--lv-muted);font-size:10px;}.bl-note{overflow:hidden;margin:13px 0 0;color:var(--lv-muted);font-size:12px;text-overflow:ellipsis;white-space:nowrap;}.bl-balance{display:flex;flex-direction:column;gap:7px;margin:19px 0 16px;}.bl-balance>span{color:var(--lv-muted);font-size:10px;}.bl-balance strong{color:var(--lv-accent);font-size:25px;letter-spacing:-.8px;font-weight:700;font-variant-numeric:tabular-nums;}.bl-flows{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:16px;}.bl-flows>span{display:flex;flex-direction:column;gap:6px;}.bl-flows small{color:var(--lv-muted);font-size:10px;}.bl-flows b{font-size:13px;font-weight:650;font-variant-numeric:tabular-nums;}.bl-budget{margin-top:0;margin-bottom:16px;}.bl-budget>div{display:flex;justify-content:space-between;margin-bottom:6px;color:var(--lv-muted);font-size:9px;}.bl-budget>i{display:block;height:4px;overflow:hidden;border-radius:5px;background:var(--lv-line);}.bl-budget>i>b{display:block;height:100%;border-radius:5px;background:var(--book-color);}
.bl-open>footer{display:flex;align-items:center;justify-content:space-between;gap:9px;margin-top:auto;padding-top:12px;border-top:1px solid var(--lv-line);color:var(--lv-muted);font-size:9px;}.bl-period{display:flex;align-items:center;gap:6px;min-width:0;}.bl-period>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}.bl-open>footer>span:last-child{flex:none;}.bl-card-menu{position:absolute;top:17px;right:11px;}
.bl-empty{display:flex;align-items:center;flex-direction:column;padding:44px 20px;border:1px dashed var(--lv-line);border-radius:20px;background:var(--lv-paper);text-align:center;}.bl-empty>span{display:grid;place-items:center;width:62px;height:62px;border-radius:21px;background:var(--lv-soft);color:var(--lv-accent);}.bl-empty h3{margin:17px 0 8px;font-size:16px;}.bl-empty p{margin:0 0 18px;font-size:12px;color:var(--lv-muted);}
@media(max-width:600px){.book-library{gap:16px;}.bl-intro h2{font-size:21px;}.bl-intro p{max-width:220px;font-size:11px;}.bl-intro .lv-button{padding:8px 10px;font-size:11px;}.bl-overview{gap:8px;}.bl-overview>div{padding:13px 11px;border-radius:14px;}.bl-overview b{font-size:16px;}.bl-overview small{font-size:10px;}.bl-grid{gap:12px;}.bl-toolbar{gap:8px;}.bl-toolbar :deep(.lv-menu-trigger){padding:7px 9px;font-size:10px;}.bl-open{padding:17px 17px 14px;}}
.bl-balance strong.lv-expense{color:var(--lv-expense);}
</style>
